package com.technext.pay.payment;
import com.technext.pay.identity.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class OrderService{
 private final MerchantRepository merchants;private final PaymentOrderRepository orders;public OrderService(MerchantRepository m,PaymentOrderRepository o){merchants=m;orders=o;}
 @Transactional public PaymentOrder create(UUID merchantId,long amount,String currency,String description,String key){if(amount<100)throw new IllegalArgumentException("minimum_amount_is_100_paise");if(!"INR".equals(currency))throw new IllegalArgumentException("unsupported_currency");if(key==null||key.isBlank()||key.length()>100)throw new IllegalArgumentException("idempotency_key_required");Merchant merchant=merchants.findLockedById(merchantId).orElseThrow(()->new IllegalArgumentException("merchant_not_found"));return orders.findByMerchantIdAndIdempotencyKey(merchantId,key).orElseGet(()->orders.save(new PaymentOrder(merchant,amount,currency,description,key)));}
 @Transactional public PaymentOrder simulate(UUID merchantId,UUID orderId,SandboxOutcome outcome,String environment){if(!"TEST".equals(environment))throw new IllegalArgumentException("sandbox_only");PaymentOrder order=orders.findByIdAndMerchantId(orderId,merchantId).orElseThrow(()->new IllegalArgumentException("order_not_found"));PaymentStatus next=switch(outcome){case SUCCESS,CAPTURED->PaymentStatus.CAPTURED;case AUTHORIZED->PaymentStatus.AUTHORIZED;case FAILED,DECLINED,TIMEOUT,WEBHOOK_FAILURE->PaymentStatus.FAILED;case REFUND->PaymentStatus.REFUNDED;case PARTIAL_REFUND->PaymentStatus.PARTIALLY_REFUNDED;};if(order.getStatus()==PaymentStatus.CREATED)order.transition(PaymentStatus.INITIATED);if((next==PaymentStatus.REFUNDED||next==PaymentStatus.PARTIALLY_REFUNDED)&&(order.getStatus()==PaymentStatus.INITIATED||order.getStatus()==PaymentStatus.AUTHORIZED))order.transition(PaymentStatus.CAPTURED);order.transition(next);return order;}
 @Transactional(readOnly=true) public PaymentOrder get(UUID merchantId,UUID id){return orders.findByIdAndMerchantId(id,merchantId).orElseThrow(()->new IllegalArgumentException("order_not_found"));}
 @Transactional(readOnly=true) public List<PaymentOrder> list(UUID merchantId){return orders.findTop100ByMerchantIdOrderByCreatedAtDesc(merchantId);}
}

